    static boolean blocked(SharedPreferences p, String url) {
        if (!p.getBoolean("x_ads", true) || url == null) return false;
        String h = url.toLowerCase();
        int i = h.indexOf("://");
        if (i >= 0) h = h.substring(i + 3);
        for (String a : ADS) if (h.startsWith(a) || h.contains("." + a) || h.contains("/" + a)) return true;
        return false;
    }

